create table calendar_events (created_at timestamp(6) with time zone not null, end_at timestamp(6) with time zone not null, id bigint generated by default as identity, start_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, title varchar(200) not null, description varchar(2000), primary key (id));
create table completion_activity (estimated_minutes integer, completed_at timestamp(6) with time zone not null, task_id bigint not null, primary key (task_id));
create table email_delivery (last_attempt_at timestamp(6) with time zone, sent_at timestamp(6) with time zone, delivery_key varchar(250) not null, primary key (delivery_key));
create table email_preferences (enabled boolean not null, verified boolean default false not null, id bigint not null, last_verification_sent timestamp(6) with time zone, verification_expires timestamp(6) with time zone, verification_hash varchar(64), pending_recipient varchar(254), recipient varchar(254), primary key (id));
create table mail_candidates (end_at timestamp(6) with time zone, event_id bigint, id bigint generated by default as identity, start_at timestamp(6) with time zone, status varchar(20), message_id varchar(100) not null, title varchar(200), account varchar(254) not null, reason varchar(500), primary key (id), unique (account, message_id));
create table notes (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, title varchar(200) not null, content varchar(20000) not null, primary key (id));
create table planned_blocks (created_at timestamp(6) with time zone not null, end_at timestamp(6) with time zone not null, id bigint generated by default as identity, start_at timestamp(6) with time zone not null, task_id bigint not null, primary key (id), unique (task_id));
create table tasks (estimated_minutes integer, recurrence_spawned boolean default false not null, reminder_enabled boolean default false not null, reminder_minutes_before integer default 0 not null, completed_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, due_date timestamp(6) with time zone, id bigint generated by default as identity, reminder_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, title varchar(200) not null, description varchar(5000), time_zone varchar(255), priority enum ('HIGH','LOW','MEDIUM') not null, recurrence enum ('DAILY','MONTHLY','NONE','WEEKLY'), status enum ('COMPLETED','IN_PROGRESS','TODO') not null, primary key (id));
create table user_settings (daily_task_goal integer not null, work_end time(0) not null, work_start time(0) not null, id bigint not null, updated_at timestamp(6) with time zone not null, time_zone varchar(100) not null, primary key (id));
